                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            rA0 = fj_v;
        }
        double rA1;
        {
            auto fj_v = gA1;
            for (int32_t fj_o = FJ_WAVEFRONT / 2; fj_o > 0; fj_o /= 2) {
                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            rA1 = fj_v;
        }
        double rA2;
        {
            auto fj_v = gA2;
            for (int32_t fj_o = FJ_WAVEFRONT / 2; fj_o > 0; fj_o /= 2) {
                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            rA2 = fj_v;
        }
        double rC0;
        {
            auto fj_v = gC0;
            for (int32_t fj_o = FJ_WAVEFRONT / 2; fj_o > 0; fj_o /= 2) {
                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            rC0 = fj_v;
        }
        double rC1;
        {
            auto fj_v = gC1;
            for (int32_t fj_o = FJ_WAVEFRONT / 2; fj_o > 0; fj_o /= 2) {
                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            rC1 = fj_v;
        }
        double rC2;
        {
            auto fj_v = gC2;
            for (int32_t fj_o = FJ_WAVEFRONT / 2; fj_o > 0; fj_o /= 2) {
                fj_v += __shfl_xor_sync(FJ_FULL_LANE_MASK, fj_v, fj_o, FJ_WAVEFRONT);
            }
            rC2 = fj_v;
        }
        // AtomicAdd by lane 0: every bra record on an atom adds into that atom's row
        // of G
        if (static_cast<int32_t>(threadIdx.y) < 1) {
            atomicAdd(&G[(aa * 3 + 0)], (sb * rA0));
            atomicAdd(&G[(aa * 3 + 1)], (sb * rA1));
            atomicAdd(&G[(aa * 3 + 2)], (sb * rA2));
            atomicAdd(&G[(ac * 3 + 0)], (sb * rC0));
            atomicAdd(&G[(ac * 3 + 1)], (sb * rC1));
            atomicAdd(&G[(ac * 3 + 2)], (sb * rC2));
        }
    }
}
